-- ── SELF-CHECK ───────────────────────────────────────────────────────────
do $$
declare v_n int; v_bad text;
begin
  -- Scoped to THIS generator's rows: another migration's families live in the
  -- same table and are none of this count's business.
  select count(*) into v_n from public.hr_unlock_offers where source = 'gen-unlock-offers'
     and table_name <> all (array['companion']::text[]);
  if v_n <> 45 then
    raise exception 'hr_unlock_offers holds % gen-unlock-offers rows, expected 45 — the insert was partial', v_n;
  end if;
  select count(*) into v_n from public.hr_unlock_offers
   where source = 'gen-unlock-offers' and refusal is null
     and table_name <> all (array['companion']::text[]);
  if v_n <> 35 then
    raise exception 'hr_unlock_offers holds % sellable gen-unlock-offers rows, expected 35', v_n;
  end if;
  -- ⚠ THE INTERLOCK. A refill that deleted a family this file does not own is
  --   the production incident this scoping exists to prevent, and an assertion
  --   is the only thing that notices if the scoping is ever "simplified" away.
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'hr_unlock_offers'
                and column_name = 'source' and column_default is null) then
    raise exception 'hr_unlock_offers.source lost its default — a row inserted without an owner '
                    'would be deleted by the next refill of whichever tool guessed first';
  end if;

  -- ⚠ THE CROSS-CATALOGUE JOIN. This table says what a purchase costs;
  --   hr_unlocks says how the row it writes MERGES. A sellable offer whose
  --   unlock id is not in hr_unlocks, or is not stored as a level, would be
  --   sold and then refused by the storage guard — a player charged for a
  --   bad_delta. Checked here rather than trusted, because the two files are
  --   generated by two tools from two sources.
  if to_regclass('public.hr_unlocks') is null then
    raise exception 'hr_unlocks is absent — apply 2026-08-16-unlocks.generated.sql first. This '
                    'table prices grants whose MERGE RULE lives there; without it every sellable '
                    'row is unverifiable.';
  end if;
  select string_agg(o.offer_id, ', ') into v_bad
    from public.hr_unlock_offers o
    left join public.hr_unlocks u on u.unlock_id = o.unlock_id
   where o.refusal is null
     and (u.unlock_id is null or u.progress_kind is null
          or not (o.value = any (coalesce(u.rungs, array[]::int[])))
          or (u.max_value is not null and o.value > u.max_value));
  if v_bad is not null then
    raise exception 'sellable offers whose grant is not a rung the unlock catalogue knows: %', v_bad;
  end if;

  -- Every item this table names, sellable or refused, and every blueprint it
  -- can consume, must be an item the apply engine's catalogue knows (Security
  -- R2, 2026-10-15: no row may name an item missing from hr_items).
  if to_regclass('public.hr_items') is not null then
    select string_agg(x.offer_id, ', ') into v_bad from (
      select o.offer_id, k as item_id
        from public.hr_unlock_offers o, jsonb_object_keys(coalesce(o.items,'{}'::jsonb)) k
      union all
      select o.offer_id, o.req_item from public.hr_unlock_offers o where o.req_item is not null) x
     where not exists (select 1 from public.hr_items i where i.item_id = x.item_id);
    if v_bad is not null then
      raise exception 'unlock offers costing items that are not in hr_items: %', v_bad;
    end if;
  end if;

  -- A PRICE A PLAYER CAN PAY (lane c-house-pelts). The rows held until their content exists are refused,
  -- and no sellable row costs an item the catalogue's generator found no door to.
  select string_agg(o.offer_id, ', ') into v_bad from public.hr_unlock_offers o
   where o.offer_id = any (array[]::text[]) and o.refusal is null;
  if v_bad is not null then
    raise exception 'held house rows are sellable: %', v_bad;
  end if;
  select string_agg(o.offer_id, ', ') into v_bad from public.hr_unlock_offers o
   where o.source = 'gen-unlock-offers' and o.refusal is null
     and coalesce(o.items, '{}'::jsonb) ?| array[]::text[];
  if v_bad is not null then
    raise exception 'sellable house rows cost an item no player can reach: %', v_bad;
  end if;

  -- A BENCH AT HOME IS A LONG GOAL (lane/b-bench-prices, Tyler 2026-11-01: "make building workbenches in your house WAY more
  -- expensive"). The first rung of a room that frees its skill from the public bench's tax is a week's money, and no rung
  -- of any room costs less gold than the one below it.
  select string_agg(o.offer_id, ', ') into v_bad from public.hr_unlock_offers o
   where o.offer_id in ('room.kitchen.1', 'room.forge.1', 'room.workshop.1', 'room.library.1') and o.gold < 40000;
  if v_bad is not null then
    raise exception 'a bench room''s first rung is under 40,000 gold: %', v_bad;
  end if;
  select string_agg(a.offer_id, ', ') into v_bad from public.hr_unlock_offers a
    join public.hr_unlock_offers b on b.unlock_id = a.unlock_id and b.value = a.value + 1
   where a.table_name = 'room' and b.table_name = 'room' and b.gold < a.gold;
  if v_bad is not null then
    raise exception 'a room''s next rung costs less gold than: %', v_bad;
  end if;

  -- THE KITCHEN IS SELLABLE. Everything downstream of this file exists so that
  -- a server-owned Kitchen rung can make 'artisan' payable; a table that lost
  -- it would still pass every check above.
  select count(*) into v_n from public.hr_unlock_offers
   where refusal is null and unlock_id = 'room:kitchen';
  if v_n < 1 then
    raise exception 'no sellable room:kitchen rung — noBurn has no server-owned writer and '
                    '''artisan'' cannot become payable';
  end if;

  raise notice 'hr_unlock_offers OK — % rows, % sellable (property=5 · room=30)', 45, 35;
end $$;

-- ── ROOMS HELD WHOLE, AS THE PURCHASE SEES THEM (src/data/homestead-tiers.js HELD_HOME_ROOMS) ──
-- A room held until it is rebuilt (the Trophy Room, 2026-11-20: it sold a wall that hangs nothing) sells no rung, and
-- every other room still sells. Proved by EXECUTING hr_unlock_buy as a probe account that owns the home tier, the gold
-- and the materials (and any blueprint) for every room's first rung: each held rung is refused offer_unsupported with a
-- held: reason, and every other room's first rung is bought. The probe is rolled back whole (a sentinel exception), so no
-- row of it outlives this block, which a second apply proves byte-identical.
do $$
declare
  c_u    uuid := gen_random_uuid();
  c_held text[] := array['room:trophy', 'room:shrine']::text[];
  v      jsonb;
  v_r    record;
  v_tier int;
  v_n    int := 0;
begin
  begin
    insert into auth.users (id) values (c_u);
    insert into public.hr_access_allowlist (user_id, note) values (c_u, 'gen-unlock-offers held-room probe') on conflict (user_id) do nothing;
    perform set_config('request.jwt.claim.sub', c_u::text, true);
    perform set_config('request.jwt.claims', jsonb_build_object('sub', c_u, 'role', 'authenticated')::text, true);
    v := public.hr_create_character(0);
    if coalesce(v->>'ok', '') <> 'true' then raise exception 'held rooms probe: hr_create_character refused: %', v; end if;
    select coalesce(max(o.req_property_tier), 0) into v_tier from public.hr_unlock_offers o
     where o.table_name = 'room' and o.value = 1 and o.refusal is null;
    insert into public.player_progress (user_id, slot, kind, key, value, period_key)
      select c_u, 0, u.progress_kind, u.unlock_id, o.value, '' from public.hr_unlock_offers o
        join public.hr_unlocks u on u.unlock_id = o.unlock_id
       where o.table_name = 'property' and o.refusal is null and o.value = v_tier;
    if public.hr_account_property_tier(c_u) <> v_tier then raise exception 'held rooms probe: the home is tier %, want %', public.hr_account_property_tier(c_u), v_tier; end if;
    insert into public.account_wallet as w (user_id, gold)
      select c_u, sum(o.gold)::bigint from public.hr_unlock_offers o where o.table_name = 'room' and o.value = 1 and o.refusal is null
    on conflict (user_id) do update set gold = excluded.gold;
    insert into public.player_inventory (user_id, slot, item_id, qty)
      select c_u, 0, x.k, sum(x.n) from (
        select e.item_k as k, e.item_n::bigint as n from public.hr_unlock_offers o, jsonb_each_text(o.items) e(item_k, item_n)
         where o.table_name = 'room' and o.value = 1 and o.refusal is null
        union all
        select o.req_item, 1 from public.hr_unlock_offers o
         where o.table_name = 'room' and o.value = 1 and o.refusal is null and o.req_item is not null) x
      group by x.k
    on conflict (user_id, slot, item_id) do update set qty = excluded.qty;
    -- every held rung, forged: refused by name before any lock
    for v_r in select o.offer_id from public.hr_unlock_offers o where o.unlock_id = any (c_held) order by o.offer_id loop
      v := public.hr_unlock_buy(null, 0, (select version from public.player_state where user_id = c_u and slot = 0), gen_random_uuid(), v_r.offer_id);
      if coalesce(v->>'error', '') <> 'offer_unsupported' or coalesce(v->'detail'->>'reason', '') not like 'held:%' then
        raise exception 'a held room''s rung % answered %, want offer_unsupported (held:)', v_r.offer_id, v;
      end if;
      v_n := v_n + 1;
    end loop;
    if v_n <> (select count(*) from public.hr_unlock_offers o where o.unlock_id = any (c_held)) or cardinality(c_held) > 0 and v_n = 0 then
      raise exception 'held rooms probe: % held rungs tried', v_n;
    end if;
    -- every other room's first rung: bought
    v_n := 0;
    for v_r in select o.offer_id from public.hr_unlock_offers o
                where o.table_name = 'room' and o.value = 1 and o.refusal is null order by o.offer_id loop
      v := public.hr_unlock_buy(null, 0, (select version from public.player_state where user_id = c_u and slot = 0), gen_random_uuid(), v_r.offer_id);
      if coalesce(v->>'ok', '') <> 'true' then raise exception 'a room that is not held refused its first rung %: %', v_r.offer_id, v; end if;
      v_n := v_n + 1;
    end loop;
    if v_n <> 6 then raise exception 'held rooms probe: % rooms sold their first rung, want 6', v_n; end if;
    raise exception using errcode = 'HRH01', message = 'held rooms probe: rolled back';
  exception when sqlstate 'HRH01' then null;
  end;
  perform set_config('request.jwt.claim.sub', '', true);
  perform set_config('request.jwt.claims', '', true);
  if exists (select 1 from auth.users where id = c_u) or exists (select 1 from public.player_state where user_id = c_u) then
    raise exception 'held rooms probe: LEAKED a probe row';
  end if;
  raise notice 'held rooms OK: % held, 6 other rooms sell their first rung', cardinality(c_held);
end $$;

-- ── THE DEED LADDER, AS THE PURCHASE SEES IT (src/data/shops.js property.*; Tyler 2026-11-20, balance call 26-3) ──
-- 401 / 25,468 / 145,180 / 593,554 / 2,582,720 gold. Proved by EXECUTING hr_unlock_buy as a probe account with every deed's
-- gold and materials: a deed above the next one is refused (the spine), each is then bought in order for exactly its gold, and the
-- account ends at the top tier. Rolled back whole (a sentinel exception); a second apply proves it byte-identical.
do $$
declare
  c_u    uuid := gen_random_uuid();
  c_want text := '1:401,2:25468,3:145180,4:593554,5:2582720';
  v      jsonb;
  v_r    record;
  v_g0   bigint;
  v_got  text := '';
begin
  begin
    insert into auth.users (id) values (c_u);
    insert into public.hr_access_allowlist (user_id, note) values (c_u, 'gen-unlock-offers deed ladder probe') on conflict (user_id) do nothing;
    perform set_config('request.jwt.claim.sub', c_u::text, true);
    perform set_config('request.jwt.claims', jsonb_build_object('sub', c_u, 'role', 'authenticated')::text, true);
    v := public.hr_create_character(0);
    if coalesce(v->>'ok', '') <> 'true' then raise exception 'deed ladder probe: hr_create_character refused: %', v; end if;
    insert into public.account_wallet as w (user_id, gold)
      select c_u, sum(o.gold)::bigint from public.hr_unlock_offers o where o.table_name = 'property' and o.refusal is null
    on conflict (user_id) do update set gold = excluded.gold;
    insert into public.player_inventory (user_id, slot, item_id, qty)
      select c_u, 0, e.item_k, sum(e.item_n::bigint) from public.hr_unlock_offers o, jsonb_each_text(o.items) e(item_k, item_n)
       where o.table_name = 'property' and o.refusal is null
       group by e.item_k
    on conflict (user_id, slot, item_id) do update set qty = excluded.qty;
    -- the spine: the second deed is refused while the first is not owned, and nothing is charged
    v_g0 := public.hr_purse_of(c_u);
    v := public.hr_unlock_buy(null, 0, (select version from public.player_state where user_id = c_u and slot = 0), gen_random_uuid(),
           (select o.offer_id from public.hr_unlock_offers o where o.table_name = 'property' and o.refusal is null order by o.value offset 1 limit 1));
    if coalesce(v->>'ok', '') = 'true' or public.hr_purse_of(c_u) <> v_g0 then
      raise exception 'deed ladder probe: a deed past the next one answered % and the purse moved % -> %', v, v_g0, public.hr_purse_of(c_u); end if;
    -- each deed in order, for exactly its gold
    for v_r in select o.offer_id, o.value, o.gold from public.hr_unlock_offers o where o.table_name = 'property' and o.refusal is null order by o.value loop
      v_g0 := public.hr_purse_of(c_u);
      v := public.hr_unlock_buy(null, 0, (select version from public.player_state where user_id = c_u and slot = 0), gen_random_uuid(), v_r.offer_id);
      if coalesce(v->>'ok', '') <> 'true' then raise exception 'deed ladder probe: % refused: %', v_r.offer_id, v; end if;
      v_got := v_got || case when v_got = '' then '' else ',' end || v_r.value || ':' || (v_g0 - public.hr_purse_of(c_u));
    end loop;
    if v_got is distinct from c_want then
      raise exception 'deed ladder probe: the deeds sold as % (tier:gold), the data says %', v_got, c_want; end if;
    if public.hr_account_property_tier(c_u) <> 5 then
      raise exception 'deed ladder probe: the account ends at tier %', public.hr_account_property_tier(c_u); end if;
    raise exception using errcode = 'HRH02', message = 'deed ladder probe: rolled back';
  exception when sqlstate 'HRH02' then null;
  end;
  perform set_config('request.jwt.claim.sub', '', true);
  perform set_config('request.jwt.claims', '', true);
  if exists (select 1 from auth.users where id = c_u) or exists (select 1 from public.player_state where user_id = c_u) then
    raise exception 'deed ladder probe: LEAKED a probe row';
  end if;
  raise notice 'deed ladder OK: % (tier:gold), each in order', c_want;
end $$;
